/**
 * Parses the optional `### Model overrides` subsection from a task's entry in tasks.md.
 *
 * Returns { [phase]: { allowed, default } } for each declared phase.
 * Returns an empty object when the subsection is absent or cannot be parsed
 * (with a model_override_parse_warning event emitted to stdout).
 */

import { parse as parseYaml } from "yaml";

/** The five phases for which model selection is defined. */
export type Phase =
  | "implementation"
  | "self_review"
  | "pr_description"
  | "suggested_next_step"
  | "conflict_resolution";

/** Model allowlist for one execution phase. */
export interface PhasePolicy {
  /** Model IDs the agent may use for this phase. */
  allowed: string[];
  /** Model to use by default; must be in allowed. */
  default: string;
}

/** Task-level model overrides keyed by phase. Only declared phases are present. */
export type ModelOverrides = Partial<Record<Phase, PhasePolicy>>;

/** Emitted to stdout when a ### Model overrides section cannot be parsed. */
export interface ModelOverrideParseWarning {
  type: "model_override_parse_warning";
  taskId: string;
  reason: string;
}

const VALID_PHASES = new Set<string>([
  "implementation",
  "self_review",
  "pr_description",
  "suggested_next_step",
  "conflict_resolution",
]);

function emitWarning(warning: ModelOverrideParseWarning): void {
  console.log(JSON.stringify(warning));
}

/**
 * Extract the raw text content of the `### Model overrides` block for a given
 * task from the full tasks.md text.
 *
 * Scoping rules:
 *   - Task section starts at `## T<n>` heading line.
 *   - Task section ends at the next `## ` heading or EOF.
 *   - Model overrides block starts at `### Model overrides` within the section.
 *   - Block ends at the next `### ` / `## ` heading or end of task section.
 */
function extractModelOverridesBlock(tasksmd: string, taskId: string): string | null {
  const numericId = taskId.replace(/^T/, "");

  // Find the heading line for this task
  const headingRegex = new RegExp(`^## T${numericId}(?:[ \\t]|$)`, "m");
  const headingMatch = headingRegex.exec(tasksmd);
  if (!headingMatch) return null;

  // Skip to after this heading line
  const headingLineEnd = tasksmd.indexOf("\n", headingMatch.index);
  if (headingLineEnd === -1) return null;
  const afterHeading = tasksmd.slice(headingLineEnd + 1);

  // Scope to this task's section (ends at next ## heading)
  const nextHeadingMatch = /^## /m.exec(afterHeading);
  const taskSection = nextHeadingMatch
    ? afterHeading.slice(0, nextHeadingMatch.index)
    : afterHeading;

  // Find ### Model overrides within this section
  const overridesMatch = /^### Model overrides[ \t]*\n/m.exec(taskSection);
  if (!overridesMatch) return null;

  const afterOverrides = taskSection.slice(
    overridesMatch.index + overridesMatch[0].length,
  );

  // Block ends at the next subsection heading or end of task section
  const nextSubsectionMatch = /^##+ /m.exec(afterOverrides);
  const block = nextSubsectionMatch
    ? afterOverrides.slice(0, nextSubsectionMatch.index)
    : afterOverrides;

  return block.trim();
}

function isValidPhasePolicy(val: unknown): val is PhasePolicy {
  if (typeof val !== "object" || val === null || Array.isArray(val)) return false;
  const obj = val as Record<string, unknown>;
  return (
    Array.isArray(obj["allowed"]) &&
    (obj["allowed"] as unknown[]).every((m) => typeof m === "string") &&
    (obj["allowed"] as unknown[]).length > 0 &&
    typeof obj["default"] === "string" &&
    (obj["default"] as string).length > 0
  );
}

/**
 * Parse the `### Model overrides` subsection for a given task from tasks.md text.
 *
 * @param tasksmd - Full text of the tasks.md file.
 * @param taskId  - Task ID, e.g. "T3".
 * @returns Parsed overrides for declared phases; empty object if absent or malformed.
 */
export function parseModelOverrides(tasksmd: string, taskId: string): ModelOverrides {
  const block = extractModelOverridesBlock(tasksmd, taskId);
  if (block === null || block === "") return {};

  let parsed: unknown;
  try {
    parsed = parseYaml(block);
  } catch (e) {
    emitWarning({
      type: "model_override_parse_warning",
      taskId,
      reason: `YAML parse error in ### Model overrides: ${(e as Error).message}`,
    });
    return {};
  }

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    emitWarning({
      type: "model_override_parse_warning",
      taskId,
      reason: "### Model overrides block must be a YAML mapping",
    });
    return {};
  }

  const result: ModelOverrides = {};

  for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
    if (!VALID_PHASES.has(key)) {
      emitWarning({
        type: "model_override_parse_warning",
        taskId,
        reason: `Unknown phase "${key}" — skipping. Valid phases: ${[...VALID_PHASES].join(", ")}`,
      });
      continue;
    }
    if (!isValidPhasePolicy(value)) {
      emitWarning({
        type: "model_override_parse_warning",
        taskId,
        reason: `Phase "${key}" must have allowed (non-empty string array) and default (non-empty string) — skipping`,
      });
      continue;
    }
    result[key as Phase] = value;
  }

  return result;
}
/**
 * Merges workspace-level model_policy with task-level ### Model overrides
 * and returns the effective model selection for a given phase.
 *
 * Merge rule: task-level overrides replace the workspace default for each
 * declared phase. Undeclared phases inherit workspace defaults.
 */

import type { Phase, PhasePolicy, ModelOverrides } from "./parse-model-overrides.js";

export type { Phase, PhasePolicy };

/** Full workspace model_policy (all five phases required). */
export interface ModelPolicy {
  implementation: PhasePolicy;
  self_review: PhasePolicy;
  pr_description: PhasePolicy;
  suggested_next_step: PhasePolicy;
  conflict_resolution: PhasePolicy;
}

/** Emitted to stdout when the resolved default is not in allowed. */
export interface ModelFallbackEvent {
  type: "model_fallback";
  taskId: string;
  phase: Phase;
  requested: string;
  fallback: string;
  reason: string;
}

function emitFallback(event: ModelFallbackEvent): void {
  console.log(JSON.stringify(event));
}

/**
 * Resolve the effective PhasePolicy for a given phase by merging workspace
 * defaults with task-level overrides.
 *
 * If the resolved default is not in the allowed list (configuration error),
 * falls back to the first item in allowed and emits a model_fallback event.
 *
 * @param workspacePolicy - workspace.yaml model_policy (all phases present).
 * @param taskOverrides   - Parsed task-level overrides from parse-model-overrides.
 * @param phase           - The phase to resolve.
 * @param taskId          - Used in fallback events for diagnostics.
 */
export function resolvePhasePolicy(
  workspacePolicy: ModelPolicy,
  taskOverrides: ModelOverrides,
  phase: Phase,
  taskId: string,
): PhasePolicy {
  const base = workspacePolicy[phase];
  const override = taskOverrides[phase];
  const effective: PhasePolicy = override ?? base;

  if (!effective.allowed.includes(effective.default)) {
    const fallback = effective.allowed[0]!;
    emitFallback({
      type: "model_fallback",
      taskId,
      phase,
      requested: effective.default,
      fallback,
      reason: `default model "${effective.default}" is not in allowed list [${effective.allowed.join(", ")}] — falling back to "${fallback}"`,
    });
    return { ...effective, default: fallback };
  }

  return effective;
}

/**
 * Resolve the effective model ID for a given phase.
 * The most common call site — returns just the default model string.
 *
 * @param workspacePolicy - workspace.yaml model_policy.
 * @param taskOverrides   - Parsed task-level overrides.
 * @param phase           - The phase to resolve.
 * @param taskId          - Used in fallback events for diagnostics.
 */
export function resolveModel(
  workspacePolicy: ModelPolicy,
  taskOverrides: ModelOverrides,
  phase: Phase,
  taskId: string,
): string {
  return resolvePhasePolicy(workspacePolicy, taskOverrides, phase, taskId).default;
}
import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import Ajv, { type ValidateFunction, type ErrorObject } from "ajv";
import { parse as parseYaml } from "yaml";

/** Validated agent configuration. */
export interface AgentConfig {
  /** SSH URLs of workspace repositories this agent watches. */
  watches: string[];
  /** Kill switch — false means exit immediately. */
  enabled: boolean;
  /** Maximum random jitter (seconds) before a claim commit. */
  jitter_max_seconds: number;
  /** Hard budget limits per task activation. */
  budget: {
    /** Max tokens (input + output) per task. */
    max_tokens_per_task: number;
    /** Max tool-use loop iterations per task. */
    max_iterations: number;
  };
  /** Per-run JSONL event log configuration. */
  log_sink: {
    /** Whether to write event logs. */
    enabled: boolean;
  };
  /**
   * Seconds to sleep between poll cycles when no eligible task is found,
   * and after a successful task run.
   * Set to 0 for single-shot mode (process exits after one cycle).
   * Defaults to 60 when omitted.
   */
  idle_sleep_seconds?: number;
  /**
   * Maximum number of executor processes/containers that may run concurrently.
   * Defaults to 1 for local-subprocess (shared filesystem — no concurrent git ops).
   * Defaults to 4 for local-docker (isolated containers — resource limit only).
   */
  max_concurrent_executors?: number;
}

export interface ValidationError {
  /** JSON pointer to the offending field (e.g. "/budget/max_tokens_per_task"). */
  path: string;
  /** Human-readable description of what went wrong. */
  message: string;
}

export type ValidationResult =
  | { valid: true; config: AgentConfig }
  | { valid: false; errors: ValidationError[] };

const __dirname = dirname(fileURLToPath(import.meta.url));
const SCHEMA_PATH = resolve(__dirname, "../../../../schemas/agent.schema.json");

let _ajvValidate: ValidateFunction | null = null;

function getValidator(schemaOverride?: object): ValidateFunction {
  if (schemaOverride) {
    const ajv = new Ajv.default({ allErrors: true });
    return ajv.compile(schemaOverride);
  }
  if (!_ajvValidate) {
    const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf-8"));
    const ajv = new Ajv.default({ allErrors: true });
    _ajvValidate = ajv.compile(schema);
  }
  return _ajvValidate;
}

function formatAjvErrors(errors: ErrorObject[]): ValidationError[] {
  return errors.map((err: ErrorObject) => {
    const path = err.instancePath || "/";
    let message: string;

    switch (err.keyword) {
      case "required":
        message = `Missing required field: ${err.params.missingProperty}`;
        break;
      case "additionalProperties":
        message = `Unknown field: ${err.params.additionalProperty}`;
        break;
      case "type":
        message = `Expected type "${err.params.type}", got ${typeof err.data}`;
        break;
      case "minimum":
        message = `Value must be >= ${err.params.limit}`;
        break;
      case "minItems":
        message = `Array must have at least ${err.params.limit} item(s)`;
        break;
      case "minLength":
        message = `String must not be empty`;
        break;
      default:
        message = err.message ?? "Validation failed";
    }

    return { path, message };
  });
}

/**
 * Parse a YAML string and validate it against the agent.yaml schema.
 * Returns the validated AgentConfig on success, or structured errors on failure.
 */
export function validateAgentYaml(
  yamlContent: string,
  options?: { schema?: object },
): ValidationResult {
  let data: unknown;
  try {
    data = parseYaml(yamlContent);
  } catch (e) {
    return {
      valid: false,
      errors: [{ path: "/", message: `YAML parse error: ${(e as Error).message}` }],
    };
  }

  if (data === null || data === undefined || typeof data !== "object") {
    return {
      valid: false,
      errors: [{ path: "/", message: "Document must be a YAML mapping (object)" }],
    };
  }

  const validate = getValidator(options?.schema);
  const isValid = validate(data);

  if (!isValid) {
    return {
      valid: false,
      errors: formatAjvErrors(validate.errors ?? []),
    };
  }

  return { valid: true, config: data as AgentConfig };
}

/**
 * Load and validate an agent.yaml file from disk.
 * Throws if the file cannot be read. Returns a ValidationResult.
 */
export function loadAgentYaml(
  filePath: string,
  options?: { schema?: object },
): ValidationResult {
  const content = readFileSync(filePath, "utf-8");
  return validateAgentYaml(content, options);
}
import { readFileSync } from "node:fs";
import { parse as parseYaml } from "yaml";
import { workspaceYamlPath } from "../paths.js";
import { parseGitHubCoords } from "../claim/open-workspace-pr.js";
import type { ModelPolicy } from "./resolve-model-policy.js";

type RepoEntry = { id: string; github: string; local_path?: string; base_branch?: string };

function readWorkspaceRepos(workspaceRoot: string): RepoEntry[] {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { repos: RepoEntry[] };
  return yaml.repos;
}

function findRepo(workspaceRoot: string, repoId: string): RepoEntry {
  const repos = readWorkspaceRepos(workspaceRoot);
  const repo = repos.find((r) => r.id === repoId);
  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
  return repo;
}

export function resolveRepoLocalPath(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  if (!repo.local_path?.startsWith("env:")) {
    throw new Error(`Repo "${repoId}" has no "local_path: env:<VAR>" declaration.`);
  }
  const envVar = repo.local_path.slice(4);
  const val = process.env[envVar];
  if (!val) throw new Error(`Env var ${envVar} is not set for repo "${repoId}".`);
  return val;
}

export function resolveRepoBaseBranch(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  return repo.base_branch ?? "main";
}

export function resolveRepoGitUrl(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  return repo.github;
}

export function loadWorkspaceModelPolicy(workspaceRoot: string): ModelPolicy {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { model_policy?: Partial<ModelPolicy> };
  const defaultPhase = { allowed: ["claude-sonnet-4-6"], default: "claude-sonnet-4-6" };
  const defaults: ModelPolicy = {
    implementation: defaultPhase,
    self_review: defaultPhase,
    pr_description: defaultPhase,
    suggested_next_step: { allowed: ["claude-haiku-4-5-20251001"], default: "claude-haiku-4-5-20251001" },
    conflict_resolution: defaultPhase,
  };
  if (!yaml.model_policy) return defaults;
  return {
    implementation: yaml.model_policy.implementation ?? defaults.implementation,
    self_review: yaml.model_policy.self_review ?? defaults.self_review,
    pr_description: yaml.model_policy.pr_description ?? defaults.pr_description,
    suggested_next_step: yaml.model_policy.suggested_next_step ?? defaults.suggested_next_step,
    conflict_resolution: yaml.model_policy.conflict_resolution ?? defaults.conflict_resolution,
  };
}

export function parseManagementRepoCoords(
  workspaceRoot: string,
): { owner: string; repo: string; baseBranch: string; repoUrl: string } {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { management_repo: string; repos: RepoEntry[] };
  const mgmtId = yaml.management_repo;
  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
  if (!mgmtRepo) throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml`);
  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main", repoUrl: mgmtRepo.github };
}

