import type { Phase, PhasePolicy, ModelOverrides } from "./parse-model-overrides.js";

export type { Phase, PhasePolicy };

/** Full workspace model_policy (all five phases required). */
export interface ModelPolicy {
  implementation: PhasePolicy;
  self_review: PhasePolicy;
  pr_description: PhasePolicy;
  suggested_next_step: PhasePolicy;
  conflict_resolution: PhasePolicy;
}

/** Emitted to stdout when the resolved default is not in allowed. */
export interface ModelFallbackEvent {
  type: "model_fallback";
  taskId: string;
  phase: Phase;
  requested: string;
  fallback: string;
  reason: string;
}

function emitFallback(event: ModelFallbackEvent): void {
  console.log(JSON.stringify(event));
}

/**
 * Resolve the effective PhasePolicy for a given phase by merging workspace
 * defaults with task-level overrides.
 *
 * If the resolved default is not in the allowed list (configuration error),
 * falls back to the first item in allowed and emits a model_fallback event.
 *
 * @param workspacePolicy - workspace.yaml model_policy (all phases present).
 * @param taskOverrides   - Parsed task-level overrides from parse-model-overrides.
 * @param phase           - The phase to resolve.
 * @param taskId          - Used in fallback events for diagnostics.
 */
export function resolvePhasePolicy(
  workspacePolicy: ModelPolicy,
  taskOverrides: ModelOverrides,
  phase: Phase,
  taskId: string,
): PhasePolicy {
  const base = workspacePolicy[phase];
  const override = taskOverrides[phase];
  const effective: PhasePolicy = override ?? base;

  if (!effective.allowed.includes(effective.default)) {
    const fallback = effective.allowed[0]!;
    emitFallback({
      type: "model_fallback",
      taskId,
      phase,
      requested: effective.default,
      fallback,
      reason: `default model "${effective.default}" is not in allowed list [${effective.allowed.join(", ")}] — falling back to "${fallback}"`,
    });
    return { ...effective, default: fallback };
  }

  return effective;
}

/**
 * Resolve the effective model ID for a given phase.
 * The most common call site — returns just the default model string.
 *
 * @param workspacePolicy - workspace.yaml model_policy.
 * @param taskOverrides   - Parsed task-level overrides.
 * @param phase           - The phase to resolve.
 * @param taskId          - Used in fallback events for diagnostics.
 */
export function resolveModel(
  workspacePolicy: ModelPolicy,
  taskOverrides: ModelOverrides,
  phase: Phase,
  taskId: string,
): string {
  return resolvePhasePolicy(workspacePolicy, taskOverrides, phase, taskId).default;
}
import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import Ajv, { type ValidateFunction, type ErrorObject } from "ajv";
import { parse as parseYaml } from "yaml";

/** Validated agent configuration. */
export interface AgentConfig {
  /** SSH URLs of workspace repositories this agent watches. */
  watches: string[];
  /** Kill switch — false means exit immediately. */
  enabled: boolean;
  /** Maximum random jitter (seconds) before a claim commit. */
  jitter_max_seconds: number;
  /** Hard budget limits per task activation. */
  budget: {
    /** Max tokens (input + output) per task. */
    max_tokens_per_task: number;
    /** Max tool-use loop iterations per task. */
    max_iterations: number;
  };
  /** Per-run JSONL event log configuration. */
  log_sink: {
    /** Whether to write event logs. */
    enabled: boolean;
  };
  /**
   * Seconds to sleep between poll cycles when no eligible task is found,
   * and after a successful task run.
   * Set to 0 for single-shot mode (process exits after one cycle).
   * Defaults to 60 when omitted.
   */
  idle_sleep_seconds?: number;
  /**
   * Maximum number of executor processes/containers that may run concurrently.
   * Defaults to 1 for local-subprocess (shared filesystem — no concurrent git ops).
   * Defaults to 4 for local-docker (isolated containers — resource limit only).
   */
  max_concurrent_executors?: number;
}

export interface ValidationError {
  /** JSON pointer to the offending field (e.g. "/budget/max_tokens_per_task"). */
  path: string;
  /** Human-readable description of what went wrong. */
  message: string;
}

export type ValidationResult =
  | { valid: true; config: AgentConfig }
  | { valid: false; errors: ValidationError[] };

const __dirname = dirname(fileURLToPath(import.meta.url));
const SCHEMA_PATH = resolve(__dirname, "../../../../schemas/agent.schema.json");

let _ajvValidate: ValidateFunction | null = null;

function getValidator(schemaOverride?: object): ValidateFunction {
  if (schemaOverride) {
    const ajv = new Ajv.default({ allErrors: true });
    return ajv.compile(schemaOverride);
  }
  if (!_ajvValidate) {
    const schema = JSON.parse(readFileSync(SCHEMA_PATH, "utf-8"));
    const ajv = new Ajv.default({ allErrors: true });
    _ajvValidate = ajv.compile(schema);
  }
  return _ajvValidate;
}

function formatAjvErrors(errors: ErrorObject[]): ValidationError[] {
  return errors.map((err: ErrorObject) => {
    const path = err.instancePath || "/";
    let message: string;

    switch (err.keyword) {
      case "required":
        message = `Missing required field: ${err.params.missingProperty}`;
        break;
      case "additionalProperties":
        message = `Unknown field: ${err.params.additionalProperty}`;
        break;
      case "type":
        message = `Expected type "${err.params.type}", got ${typeof err.data}`;
        break;
      case "minimum":
        message = `Value must be >= ${err.params.limit}`;
        break;
      case "minItems":
        message = `Array must have at least ${err.params.limit} item(s)`;
        break;
      case "minLength":
        message = `String must not be empty`;
        break;
      default:
        message = err.message ?? "Validation failed";
    }

    return { path, message };
