/**
 * Parse a YAML string and validate it against the agent.yaml schema.
 * Returns the validated AgentConfig on success, or structured errors on failure.
 */
export function validateAgentYaml(
  yamlContent: string,
  options?: { schema?: object },
): ValidationResult {
